import { moscowTime } from '../shared/report-format.mjs';
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const roles = [['analyst','Аналитик'],['reviewer','Проверяющий'],['editor','Редактор']];
const labels = { queued:'Ожидает', running:'Выполняется', completed:'Завершён', failed:'Ошибка', cancelled:'Остановлен', skipped:'Пропущен', not_started:'Не выполнялся' };
const date = s => s ? new Date(s).toLocaleString('ru-RU') : 'Не записано';
const link = (url,title) => { try { return new URL(url).protocol === 'https:' ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noreferrer">${esc(title)}</a>` : esc(title); } catch { return esc(title); } };
const detail = (title,body) => `<details class="machine"><summary>${esc(title)}</summary><div class="machine-content">${body}</div></details>`;
const list = items => `<ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
const pre = text => `<pre class="audit-text">${esc(text)}</pre>`;

export function instructions(data) {
  if (!data) return '<p>Инструкции для этого запуска не сохранены. Текущие инструкции не подставляются задним числом.</p>';
  return `${(data.roles || roles.map(([id,title])=>({id,title}))).map(role=>detail(role.title,`<p><strong>Получает:</strong> ${esc(role.receives || 'Состав входа в старом запуске не записан.')}</p><p><strong>Возвращает:</strong> ${esc(role.returns || 'Смотрите сохранённую инструкцию.')}</p>${pre(data.prompts[role.id])}`)).join('')}${detail('Методические правила',list(data.methodology.rules))}${detail('Что проверяется по 12 факторам',data.factorChecks.map(f=>`<section><h3>${esc(f.factorId)}</h3><p>${esc(f.check)}</p><p class="muted">Защита от ложной находки: ${esc(f.falsePositive)}</p></section>`).join(''))}`;
}

export function methodologyContent(data) {
  return `<div class="stack ai-methodology"><section class="card stack tight"><h2>Как ИИ проверяет документ</h2><p>Одна модель выполняет три этапа с разными инструкциями. Итоговое решение принимает специалист.</p><ul class="ai-stages"><li><strong>Аналитик</strong> находит рискованные формулировки и приводит цитаты из документа.</li><li><strong>Проверяющий</strong> сверяет замечания с текстом и правовыми основаниями. Если аргументов мало, он отмечает это.</li><li><strong>Редактор</strong> при необходимости предлагает поправку и проверяет, сохраняет ли она смысл нормы.</li></ul></section>${instructions(data)}<section class="card stack tight"><h2>Проверки приложения</h2>${list(['Цитаты должны присутствовать в документе и переданных источниках.','Ответ Аналитика должен охватывать все 12 факторов.','Каждую находку должен рассмотреть Проверяющий.','Без основания находка не получает статус «выдержала перепроверку».','Редактор проверяет права, обязанности, сроки, условия, исключения и компетенцию.','Проверка структуры и цитат не подтверждает юридическую правильность.'])}</section><div class="actions"><a class="btn" href="#quality">Контрольные примеры</a></div></div>`;
}

export function materialsContent(library) {
  if (!library) return '<p>Реестр материалов для этого запуска не записан. Нельзя достоверно восстановить его из текущей библиотеки.</p>';
  return `<p>Сверка: ${esc(library.checkedAt)} · ${esc(library.version)}</p><p>${esc(library.sync)}</p><div class="notice"><h3>Учебные материалы и правовые основания имеют разный статус</h3><p>${esc(library.readingLimitations)} Материалы закреплены в версии приложения и не зависят от памяти чата. В модель передаются выбранные методические правила, а не все исходные файлы.</p></div>${library.files.map(f=>`<section class="card stack tight"><h2>${esc(f.name)}</h2><p>${f.usedInPrompts?'Выбранные положения перенесены в инструкции':'Справочный контекст · в запросы не включён'} · ${f.pages} слайдов / страниц</p><p>${esc(f.scope)}</p><p>${esc(f.transmission)}</p><p class="muted">${esc(f.readingLimitations)}</p>${link(f.url,'Открыть оригинал на Google Диске')}${detail('Версия и проверка файла',`<p>Изменён на Диске: ${date(f.modifiedAt)}. Размер: ${f.size} байт. Доступно извлечённого текста: ${f.textLength} символов.</p><p>Размер сохранённого оригинала совпал с метаданными Диска. Хеш относится к локальному оригиналу; тождество текущих байтов Диска по хешу отдельно не проверено.</p>${pre(f.localOriginalSha256)}`)}</section>`).join('')}`;
}

export function runDetailsContent(x) {
  const r=x.r,policy=r.aiPolicy;
  return `<div class="stack"><div class="notice"><h3>${r.mode==='demo'?'Учебный сценарий':'Сохранённый состав запуска'}</h3><p>${r.mode==='demo'?'Подготовленные ответы: модель не вызывалась.':'Модель: '+esc(r.model)+'. Здесь показаны доступные данные этого запуска, а не текущие настройки.'}</p></div><section class="card stack tight"><h2>Документ и подключение</h2><p>${esc(x.d.name)} · версия ${x.v.number} · ${x.v.text.length} символов</p>${detail('Контрольная сумма документа',pre(x.v.hash))}<p>Провайдер: ${esc(r.connection?.provider || policy?.parameters?.connection?.provider || (r.mode==='demo'?'Не используется в учебном сценарии':'Не записан'))}. Запущен: ${date(r.createdAt)}.</p>${policy?.fingerprint?detail('Версия снимка инструкций',`<p>${esc(policy.snapshotOrigin==='captured_at_creation'?'Снимок создан до постановки анализа в очередь.':'Снимок зафиксирован при выполнении.')}</p>${pre(policy.fingerprint)}`):''}</section>${roles.map(([id,title])=>{
    const input=r.aiInputs?.find(i=>i.stage===id),trace=r.aiTrace?.find(t=>t.stage===id),times=r.stageTimes?.[id];
    return `<section class="card stack tight"><h2>${title} · ${esc(labels[r.stages[id]] || r.stages[id])}</h2><p>Начало: ${date(times?.startedAt)}. Завершение: ${date(times?.finishedAt)}.</p>${input?`<p>Вход: полный документ (${input.documentCharacters} символов), ${input.sourceIds.length} источников, ${input.exampleIds.length} примеров${id==='analyst'?'':', '+input.findingIds.length+' находок'}. Методика: ${esc(input.methodologyVersion)}.</p>${detail('Идентификаторы и контрольные суммы входа',pre(JSON.stringify(input,null,2)))}`:`<p>${r.mode==='demo'?'Внешнего API-запроса не было.':r.stages[id]==='skipped'?(id==='reviewer'?'Аналитик не предложил находок.':'Нет находок с основаниями, выдержавших перепроверку.'):'Вход API-запроса не записан; его состав не восстановлен задним числом.'}</p>`}${trace?detail('Ответ провайдера до программной проверки',`<p>Получен: ${date(trace.at)}. Завершение API: ${esc(trace.finishReason)}. Наличие ответа само по себе не означает, что приложение его приняло.</p>${pre(trace.response)}<p>Контрольная сумма запроса:</p>${pre(trace.requestHash)}`):''}</section>`;
  }).join('')}${r.error?`<div class="notice error"><h3>Ограничение запуска</h3><p>${esc(r.error)}</p></div>`:''}${r.mode==='demo'?'<p class="notice">Это подготовленный сценарий: запросов к модели и инструкций API в нём нет. Он не доказывает качество анализа нового документа.</p>':detail('Инструкции именно этого запуска',instructions(policy))+detail('Реестр учебных материалов этого запуска',materialsContent(policy?.materials))}${detail('Переданные правовые источники',r.sources.length?r.sources.map(s=>`<h3>${esc(s.title)}</h3><p>${esc(s.revision)} · ${esc(s.applicability)}</p>${pre(s.text)}`).join(''):'<p>Проверенные нормативные источники не переданы. Выводы ограничены; отсутствие нарушения не установлено.</p>')}${detail('Переданные примеры специалиста',r.examples.length?r.examples.map(e=>`<h3>${esc(e.title)}</h3><p>${esc(e.applicability)}</p>${pre(JSON.stringify(e,null,2))}`).join(''):'<p>Примеры не передавались.</p>')}<p class="muted">Повторный API-запрос может дать другой ответ. Сохранённый запуск и решения открываются без повторного обращения к модели.</p><div class="actions"><a class="btn" href="/api/runs/${esc(r.id)}/manifest.json" download>Скачать состав запуска</a><a class="btn" href="#results/${esc(r.id)}">К результатам</a><a class="btn" href="#sources/${esc(r.id)}">Источники запуска</a></div></div>`;
}

export function qualityContent(cases) {
  return `<div class="stack"><div class="notice"><h3>Черновой контрольный набор · ${cases.length} примеров</h3><p>Синтетические случаи для проверки ложных находок, пропусков и ограничений. Ожидания ещё не утверждены специалистом. Это не измеренная точность модели и не реальные правовые акты. В API эти примеры автоматически не передаются.</p></div>${cases.map(c=>`<section class="card stack tight"><h2>${esc(c.id)} · ${esc(c.title)}</h2><p>Ожидает утверждения специалистом</p><blockquote>${esc(c.document)}</blockquote><p><strong>Критерий проверки:</strong> ${esc(c.expected)}</p></section>`).join('')}<p>Для оценки выбранной модели нужны независимая разметка специалиста и отдельный прогон с фиксацией пропусков и ложных находок. Программные тесты проверяют правила обработки ответов и не заменяют эту оценку.</p></div>`;
}
